<section aria-labelledby="workload-inventory-heading"><h2 id="workload-inventory-heading">Container workloads</h2><ul>@forelse($items as $item)<li wire:key="workload-{{ $item->getKey() }}">{{ $item->name }} — {{ $item->status }} @if ($item->status !== 'running')<button type="button" wire:click="start('{{ $item->getKey() }}')" wire:loading.attr="disabled">Start</button>@endif @if ($item->status !== 'stopped')<button type="button" wire:click="stop('{{ $item->getKey() }}')" wire:loading.attr="disabled">Stop</button>@endif @if ($item->status !== 'running')<button type="button" wire:click="delete('{{ $item->getKey() }}')" wire:loading.attr="disabled">Delete</button>@endif</li>@empty<li>No workloads found.</li>@endforelse</ul></section>
